function i(t){if(typeof t=="number"){if(!Number.isFinite(t))throw new Error("Invalid amount");return Math.round(t*100)}const r=t.trim().replace(/,/g,"");if(!r)return 0;if(!/^-?\d*(\.\d{0,2})?$/.test(r))throw new Error("Invalid amount format");const[n,s=""]=r.split("."),o=n.startsWith("-")?-1:1,a=Math.abs(Number(n||"0")),e=(s+"00").slice(0,2);return o*(a*100+Number(e))}function c(t){const r=t<0?"-":"",n=Math.abs(t),s=Math.floor(n/100),o=String(n%100).padStart(2,"0");return`${r}${s}.${o}`}export{c as p,i as r};
